update_rule.pseudocode:
if risk_prevalence_series_source == 'exogenous':
  prevalence = exogenous_series[day]
else:
  prevalence = prevalence * (1 + trend_model(day))
risk_signal = risk_to_perception_scale * prevalence
for each person:
  person.risk_perception = (1 - risk_perception_decay) * person.risk_perception + risk_signal + outbreak_personal_weight * person.experienced_outbreak_personal

policy_active = mandate_enabled and (day >= mandate_start_day)
for each location:
  location.mask_requirement = policy_active
  location.policy_enforcement_level = clamp(location_enforcement_mean * enforcement_strength, 0, 1)
for each person at entry to location:
  exempt = Bernoulli(exemptions_rate)
  if location.mask_requirement and not exempt:
    if person not wearing:
      if Bernoulli(location.policy_enforcement_level * access_control_strictness): deny_entry or require mask
      if Bernoulli(enforcement_strength): issue penalty_amount and record
broadcast policy communication with frequency policy_communication_frequency and intensity communication_strategy_intensity -> update trust_in_authorities-weighted mask_attitude increment based on message_tone
output policy_state = {active, enforcement_strength, penalty_amount}, enforcement_profile by location type, penalties_today
